mapper.select:
SELECT fp.funding_price_id AS fundingPriceId, fp.funding_id AS fundingId, f.title AS title, fp.give_price AS amount, fp.status AS status, fp.created_at AS createdAt, fp.receipt_url AS receiptUrl FROM funding_price fp JOIN funding f ON f.funding_id = fp.funding_id WHERE fp.user_id = #{userId}
AND fp.status = 'PAID'
ORDER BY fp.created_at DESC
